      <Button
        onPress={handleSubmit(onSubmit)}
        disabled={isSubmitting}
        className="mt-2"
        size="lg"
      >
        {isSubmitting ? "Sending..." : "Send Reset Link"}
      </Button>
    </View>
  );
}

