          <Controller
            control={control}
            name="name"
            render={({ field: { onChange, onBlur, value } }) => (
              <Input
                placeholder="Full name"
                autoCapitalize="words"
                className="flex-1"
                value={value}
                onChangeText={onChange}
                onBlur={onBlur}
              />
            )}
          />
        </View>
        {errors.name && (
          <Text className="mt-1 text-sm text-destructive">{errors.name.message}</Text>
        )}
      </View>

      <View>
        <View className="flex-row items-center gap-3">
          <Mail size={20} className="text-muted-foreground" />
          <Controller
            control={control}
            name="email"
            render={({ field: { onChange, onBlur, value } }) => (
              <Input
                placeholder="Email"
                autoCapitalize="none"
                keyboardType="email-address"
                className="flex-1"
                value={value}
                onChangeText={onChange}
                onBlur={onBlur}
              />
            )}
          />
        </View>
        {errors.email && (
          <Text className="mt-1 text-sm text-destructive">{errors.email.message}</Text>
        )}
      </View>

      <View>
        <View className="flex-row items-center gap-3">
          <Lock size={20} className="text-muted-foreground" />
          <Controller
            control={control}
            name="password"
            render={({ field: { onChange, onBlur, value } }) => (
              <Input
                placeholder="Password"
                secureTextEntry
                className="flex-1"
                value={value}
                onChangeText={onChange}
                onBlur={onBlur}
              />
            )}
          />
        </View>
        {errors.password && (
          <Text className="mt-1 text-sm text-destructive">{errors.password.message}</Text>
        )}
      </View>

      <View>
        <View className="flex-row items-center gap-3">
          <Lock size={20} className="text-muted-foreground" />
          <Controller
            control={control}
            name="confirmPassword"
            render={({ field: { onChange, onBlur, value } }) => (
              <Input
                placeholder="Confirm password"
                secureTextEntry
                className="flex-1"
                value={value}
                onChangeText={onChange}
                onBlur={onBlur}
              />
            )}
          />
        </View>
        {errors.confirmPassword && (
          <Text className="mt-1 text-sm text-destructive">{errors.confirmPassword.message}</Text>
        )}
      </View>

      <Button
        onPress={handleSubmit(onSubmit)}
        disabled={isSubmitting}
        className="mt-2"
        size="lg"
      >
        {isSubmitting ? "Creating account..." : "Create Account"}
      </Button>
    </View>
  );
}

